import gleam/list
import gleam/io
import gleam/int

pub type HTMCell {
    HTMCell(active: Bool, predictive: Bool)
}

pub type HTMColumn {
    HTMColumn(active: Bool, cells: List(HTMCell))
}

pub fn initialize_htm(num_columns: Int, cells_per_column: Int) > List(HTMColumn) {
    list.map(list.range(0, num_columns), fn(_) {
        HTMColumn(active: False, cells: list.map(list.range(0, cells_per_column), fn(_) { HTMCell(active: False, predictive: False) }))
    })
}

pub fn main() {
    let columns = initialize_htm(2048, 32)
    io.println("HTM initialized: " <> int.to_string(list.length(columns)))
    Nil
}

